   181	<body>
   182	  <div class="container">
   183	    <h1>Force-Directed Network Graph</h1>
   184	    <p class="subtitle">Interactive visualization with drag, zoom, and dynamic controls</p>
   185	
   186	    <div class="stats">
   187	      <div class="stat-item">
   188	        <div class="stat-value" id="node-count">0</div>
   189	        <div class="stat-label">Nodes</div>
   190	      </div>
   191	      <div class="stat-item">
   192	        <div class="stat-value" id="link-count">0</div>
   193	        <div class="stat-label">Links</div>
   194	      </div>
   195	      <div class="stat-item">
   196	        <div class="stat-value" id="group-count">0</div>
   197	        <div class="stat-label">Groups</div>
   198	      </div>
   199	    </div>
   200	
   201	    <div class="controls">
   202	      <div class="control-group">
   203	        <label for="link-strength">Link Strength</label>
   204	        <input type="range" id="link-strength" min="0" max="2" step="0.1" value="1">
   205	        <div class="value" id="link-strength-value">1.0</div>
   206	      </div>
   207	
   208	      <div class="control-group">
   209	        <label for="charge-strength">Charge Force</label>
   210	        <input type="range" id="charge-strength" min="-500" max="-50" step="10" value="-200">
   211	        <div class="value" id="charge-strength-value">-200</div>
   212	      </div>
   213	
   214	      <div class="control-group">
   215	        <label for="collision-radius">Collision Radius</label>
   216	        <input type="range" id="collision-radius" min="5" max="50" step="1" value="20">
   217	        <div class="value" id="collision-radius-value">20</div>
   218	      </div>
   219	
   220	      <div class="control-group">
   221	        <label>&nbsp;</label>
   222	        <button id="restart-btn">Restart Simulation</button>
   223	      </div>
   224	
   225	      <div class="control-group">
   226	        <label>&nbsp;</label>
   227	        <button id="regenerate-btn">Regenerate Network</button>
   228	      </div>
   229	    </div>
   230	
   231	    <div id="chart"></div>
   232	
   233	    <div class="legend" id="legend"></div>
   234	  </div>
   235	
   236	  <div class="tooltip"></div>
   237	
   238	  <script src="https://d3js.org/d3.v7.min.js"></script>
   239	  <script>
   240	    // Generate network data
   241	    function generateNetworkData() {
   242	      const nodes = [];
   243	      const links = [];
   244	
   245	      // Create central hub
   246	      nodes.push({ id: 'hub', group: 0, size: 25, label: 'Central Hub' });
   247	
   248	      // Create groups (communities)
   249	      const numGroups = 4;
   250	      const nodesPerGroup = 6;
   251	
   252	      for (let g = 1; g <= numGroups; g++) {
   253	        // Group leader
   254	        const leaderId = `leader-${g}`;
   255	        nodes.push({
   256	          id: leaderId,
   257	          group: g,
   258	          size: 18,
   259	          label: `Leader ${g}`
   260	        });
   261	
   262	        // Connect leader to hub
   263	        links.push({
   264	          source: 'hub',
   265	          target: leaderId,
   266	          value: 5
   267	        });
   268	
   269	        // Create group members
   270	        for (let i = 1; i <= nodesPerGroup; i++) {
   271	          const nodeId = `node-${g}-${i}`;
   272	          nodes.push({
   273	            id: nodeId,
   274	            group: g,
   275	            size: 12,
   276	            label: `Node ${g}-${i}`
   277	          });
   278	
   279	          // Connect to leader
   280	          links.push({
   281	            source: leaderId,
   282	            target: nodeId,
   283	            value: 2
   284	          });
   285	
   286	          // Random connections within group
   287	          if (i > 1 && Math.random() > 0.6) {
   288	            const targetIdx = Math.floor(Math.random() * (i - 1)) + 1;
   289	            links.push({
   290	              source: nodeId,
   291	              target: `node-${g}-${targetIdx}`,
   292	              value: 1
   293	            });
   294	          }
   295	        }
   296	      }
   297	
   298	      // Add inter-group connections
   299	      for (let i = 0; i < 8; i++) {
   300	        const g1 = Math.floor(Math.random() * numGroups) + 1;
   301	        const g2 = Math.floor(Math.random() * numGroups) + 1;
   302	        if (g1 !== g2) {
   303	          const n1 = Math.floor(Math.random() * nodesPerGroup) + 1;
   304	          const n2 = Math.floor(Math.random() * nodesPerGroup) + 1;
   305	          links.push({
   306	            source: `node-${g1}-${n1}`,
   307	            target: `node-${g2}-${n2}`,
   308	            value: 1
   309	          });
   310	        }
   311	      }
   312	
   313	      return { nodes, links };
   314	    }
   315	
   316	    // Chart dimensions
   317	    const width = Math.min(window.innerWidth - 100, 1340);
   318	    const height = 700;
   319	
   320	    // Color scale
   321	    const color = d3.scaleOrdinal(d3.schemeCategory10);
   322	
   323	    // Create SVG
   324	    const svg = d3.select('#chart')
   325	      .append('svg')
   326	      .attr('width', width)
   327	      .attr('height', height)
   328	      .attr('viewBox', [0, 0, width, height]);
   329	
   330	    // Create groups for links and nodes
   331	    const linkGroup = svg.append('g').attr('class', 'links');
   332	    const nodeGroup = svg.append('g').attr('class', 'nodes');
   333	
   334	    // Create tooltip
   335	    const tooltip = d3.select('.tooltip');
   336	
   337	    // Initial data
   338	    let data = generateNetworkData();
   339	    updateStats(data);
   340	
   341	    // Force simulation
   342	    let linkForce = d3.forceLink()
   343	      .id(d => d.id)
   344	      .distance(d => 70 / d.value)
   345	      .strength(1);
   346	
   347	    let chargeForce = d3.forceManyBody()
   348	      .strength(-200);
   349	
   350	    let collisionForce = d3.forceCollide()
   351	      .radius(d => d.size + 20);
   352	
   353	    const simulation = d3.forceSimulation(data.nodes)
   354	      .force('link', linkForce.links(data.links))
   355	      .force('charge', chargeForce)
   356	      .force('center', d3.forceCenter(width / 2, height / 2))
   357	      .force('collision', collisionForce)
   358	      .on('tick', ticked);
   359	
   360	    // Create links
   361	    let link = linkGroup
   362	      .selectAll('line')
   363	      .data(data.links)
   364	      .join('line')
   365	      .attr('stroke-width', d => Math.sqrt(d.value) * 2);
   366	
   367	    // Create node groups
   368	    let node = nodeGroup
   369	      .selectAll('g')
   370	      .data(data.nodes)
   371	      .join('g')
   372	      .call(drag(simulation));
   373	
   374	    // Add circles to nodes
   375	    node.append('circle')
   376	      .attr('r', d => d.size)
   377	      .attr('fill', d => color(d.group))
   378	      .on('mouseover', handleMouseOver)
   379	      .on('mouseout', handleMouseOut)
   380	      .on('click', handleClick);
   381	
   382	    // Add labels to nodes
   383	    node.append('text')
   384	      .attr('dx', d => d.size + 5)
   385	      .attr('dy', '0.35em')
   386	      .text(d => d.label)
   387	      .style('font-size', d => d.size > 15 ? '11px' : '9px');
   388	
   389	    // Update positions on each tick
   390	    function ticked() {
   391	      link
   392	        .attr('x1', d => d.source.x)
   393	        .attr('y1', d => d.source.y)
   394	        .attr('x2', d => d.target.x)
   395	        .attr('y2', d => d.target.y);
   396	
   397	      node.attr('transform', d => `translate(${d.x},${d.y})`);
   398	    }
   399	
   400	    // Drag behavior
   401	    function drag(simulation) {
   402	      function dragstarted(event, d) {
   403	        if (!event.active) simulation.alphaTarget(0.3).restart();
   404	        d.fx = d.x;
   405	        d.fy = d.y;
   406	      }
   407	
   408	      function dragged(event, d) {
   409	        d.fx = event.x;
   410	        d.fy = event.y;
   411	      }
   412	
   413	      function dragended(event, d) {
   414	        if (!event.active) simulation.alphaTarget(0);
   415	        // Keep node fixed (comment out to allow free movement)
   416	        // d.fx = null;
   417	        // d.fy = null;
   418	      }
   419	
   420	      return d3.drag()
   421	        .on('start', dragstarted)
   422	        .on('drag', dragged)
   423	        .on('end', dragended);
   424	    }
   425	
   426	    // Event handlers
   427	    function handleMouseOver(event, d) {
   428	      // Highlight connected nodes and links
   429	      const connectedNodes = new Set([d.id]);
   430	      const connectedLinks = new Set();
   431	
   432	      data.links.forEach(l => {
   433	        if (l.source.id === d.id || l.target.id === d.id) {
   434	          connectedLinks.add(l);
   435	          connectedNodes.add(l.source.id);
   436	          connectedNodes.add(l.target.id);
   437	        }
   438	      });
   439	
   440	      // Update opacity
   441	      node.selectAll('circle')
   442	        .style('opacity', n => connectedNodes.has(n.id) ? 1 : 0.2);
   443	
   444	      link
   445	        .style('opacity', l => connectedLinks.has(l) ? 1 : 0.1)
   446	        .style('stroke', l => connectedLinks.has(l) ? '#e74c3c' : '#999');
   447	
   448	      // Show tooltip
   449	      const connections = data.links.filter(l =>
   450	        l.source.id === d.id || l.target.id === d.id
   451	      ).length;
   452	
   453	      tooltip
   454	        .classed('show', true)
   455	        .style('left', (event.pageX + 10) + 'px')
   456	        .style('top', (event.pageY - 10) + 'px')
   457	        .html(`
   458	          <strong>${d.label}</strong><br/>
   459	          <strong>ID:</strong> ${d.id}<br/>
   460	          <strong>Group:</strong> ${d.group}<br/>
   461	          <strong>Connections:</strong> ${connections}
   462	        `);
   463	    }
   464	
   465	    function handleMouseOut() {
   466	      node.selectAll('circle').style('opacity', 1);
   467	      link.style('opacity', 0.6).style('stroke', '#999');
   468	      tooltip.classed('show', false);
   469	    }
   470	
   471	    function handleClick(event, d) {
   472	      // Center on clicked node
   473	      simulation.alpha(0.3).restart();
   474	      d.fx = width / 2;
   475	      d.fy = height / 2;
   476	    }
   477	
   478	    // Controls
   479	    d3.select('#link-strength').on('input', function() {
   480	      const value = +this.value;
   481	      d3.select('#link-strength-value').text(value.toFixed(1));
   482	      linkForce.strength(value);
   483	      simulation.alpha(0.3).restart();
   484	    });
   485	
   486	    d3.select('#charge-strength').on('input', function() {
   487	      const value = +this.value;
   488	      d3.select('#charge-strength-value').text(value);
   489	      chargeForce.strength(value);
   490	      simulation.alpha(0.3).restart();
   491	    });
   492	
   493	    d3.select('#collision-radius').on('input', function() {
   494	      const value = +this.value;
   495	      d3.select('#collision-radius-value').text(value);
   496	      collisionForce.radius(d => d.size + value);
   497	      simulation.alpha(0.3).restart();
   498	    });
   499	
   500	    d3.select('#restart-btn').on('click', function() {
   501	      simulation.alpha(1).restart();
   502	    });
   503	
   504	    d3.select('#regenerate-btn').on('click', function() {
   505	      regenerateNetwork();
   506	    });
   507	
   508	    // Regenerate network
   509	    function regenerateNetwork() {
   510	      data = generateNetworkData();
   511	      updateStats(data);
   512	
   513	      // Update simulation
   514	      simulation.nodes(data.nodes);
   515	      linkForce.links(data.links);
   516	
   517	      // Update links
   518	      link = linkGroup
   519	        .selectAll('line')
   520	        .data(data.links)
   521	        .join('line')
   522	        .attr('stroke-width', d => Math.sqrt(d.value) * 2);
   523	
   524	      // Update nodes
   525	      node = nodeGroup
   526	        .selectAll('g')
   527	        .data(data.nodes)
   528	        .join('g')
   529	        .call(drag(simulation));
   530	
   531	      node.selectAll('*').remove();
   532	
   533	      node.append('circle')
   534	        .attr('r', d => d.size)
   535	        .attr('fill', d => color(d.group))
   536	        .on('mouseover', handleMouseOver)
   537	        .on('mouseout', handleMouseOut)
   538	        .on('click', handleClick);
   539	
   540	      node.append('text')
   541	        .attr('dx', d => d.size + 5)
   542	        .attr('dy', '0.35em')
   543	        .text(d => d.label)
   544	        .style('font-size', d => d.size > 15 ? '11px' : '9px');
   545	
   546	      simulation.alpha(1).restart();
   547	      updateLegend(data);
   548	    }
   549	
   550	    // Update statistics
   551	    function updateStats(data) {
   552	      d3.select('#node-count').text(data.nodes.length);
   553	      d3.select('#link-count').text(data.links.length);
   554	      const groups = new Set(data.nodes.map(d => d.group));
   555	      d3.select('#group-count').text(groups.size);
   556	    }
   557	
   558	    // Update legend
   559	    function updateLegend(data) {
   560	      const groups = [...new Set(data.nodes.map(d => d.group))].sort();
   561	
   562	      const legend = d3.select('#legend')
   563	        .selectAll('.legend-item')
   564	        .data(groups)
   565	        .join('div')
   566	        .attr('class', 'legend-item');
   567	
   568	      legend.html(d => `
   569	        <div class="legend-color" style="background-color: ${color(d)}"></div>
   570	        <span>Group ${d === 0 ? 'Hub' : d}</span>
   571	      `);
   572	    }
   573	
   574	    // Initial legend
   575	    updateLegend(data);
   576	
   577	    // Zoom behavior
   578	    const zoom = d3.zoom()
   579	      .scaleExtent([0.2, 4])
   580	      .on('zoom', (event) => {
   581	        linkGroup.attr('transform', event.transform);
   582	        nodeGroup.attr('transform', event.transform);
   583	      });
   584	
   585	    svg.call(zoom);
   586	
   587	    // Double-click to reset zoom
   588	    svg.on('dblclick.zoom', () => {
   589	      svg.transition()
   590	        .duration(750)
   591	        .call(zoom.transform, d3.zoomIdentity);
   592	    });
   593	  </script>
